from solution import count_Substrings


def test_issue_example_112112():
    """Count substrings with sum of digits equal to length gives 6 for '112112'."""
    assert count_Substrings('112112', 6) == 6  # 4+2+0+0+0+0 = 6


def test_issue_empty_string():
    """Count substrings with sum of digits equal to length is 0 for empty input."""
    assert count_Substrings('', 0) == 0  # 0*1//2 = 0


def test_issue_single_one():
    """Count substrings with sum of digits equal to length is 1 for '1'."""
    assert count_Substrings('1', 1) == 1  # 1==1 -> 1


def test_issue_single_zero():
    """Count substrings with sum of digits equal to length is 0 for '0'."""
    assert count_Substrings('0', 1) == 0  # 0!=1 -> 0


def test_issue_single_two_just_above():
    """Count substrings with sum of digits equal to length is 0 for '2' just above."""
    assert count_Substrings('2', 1) == 0  # 2!=1 -> 0


def test_issue_all_ones_three():
    """Count substrings with sum of digits equal to length is 6 for '111'."""
    assert count_Substrings('111', 3) == 6  # 3+2+1 = 6


def test_issue_no_match_two_twos():
    """Count substrings with sum of digits equal to length is 0 for '22'."""
    assert count_Substrings('22', 2) == 0  # 0+0+0 = 0


def test_issue_mixed_112():
    """Count substrings with sum of digits equal to length is 3 for '112'."""
    assert count_Substrings('112', 3) == 3  # 2+1+0 = 3


def test_issue_zero_inside_101():
    """Count substrings with sum of digits equal to length is 2 for '101'."""
    assert count_Substrings('101', 3) == 2  # 2+0+0 = 2


def test_contract_all_ones_equals_total():
    """Count with sum equal to length cannot exceed total n*(n+1)/2, equals it for '1111'."""
    assert count_Substrings('1111', 4) == 10  # 4+3+2+1 = 10


def test_contract_upper_bound_total():
    """Count with sum equal to length cannot exceed total substrings n*(n+1)/2."""
    assert count_Substrings('112112', 6) <= 21  # 6*7//2 = 21


def test_contract_nonnegative_count():
    """Count with sum equal to length must be a non-negative count of substrings."""
    assert count_Substrings('22', 2) >= 0  # 0 <= count <= 2*3//2 = 3
